arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Pricing && cat > tests/CheckoutPricing.UnitTests/Pricing/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysPoint95()
    {
        var types = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Discount"));

        Assert.True(types.Any(), "No checkout/pricing/discount type exists, so a Gold 100.00 order cannot yield 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Assert|No checkout|Passed!|Failed!" | head

